import { spawnSync } from "node:child_process";
import {
  copyFileSync,
  cpSync,
  existsSync,
  mkdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const push = process.argv.slice(2);

if (push.some((argument) => argument !== "--push") || push.length > 1) {
  throw new Error("Usage: node scripts/build-bundle.mjs [--push]");
}

const branch = spawnSync("git", ["branch", "--show-current"], {
  cwd: root,
  encoding: "utf8",
});
if (branch.error) throw branch.error;
if (branch.status !== 0 || branch.stdout.trim() !== "main") {
  throw new Error("Run this script from the main superproject branch");
}

function run(command, args, cwd = root) {
  const result = spawnSync(command, args, {
    cwd,
    stdio: "inherit",
  });

  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(" ")} failed with status ${result.status}`);
  }
}

function runNpm(command, args, cwd) {
  if (process.platform !== "win32") {
    run(command, args, cwd);
    return;
  }

  run(
    process.env.ComSpec || "cmd.exe",
    ["/d", "/s", "/c", `${command}.cmd ${args.join(" ")}`],
    cwd,
  );
}

function hasStagedChanges(cwd) {
  const result = spawnSync("git", ["diff", "--cached", "--quiet"], {
    cwd,
    stdio: "ignore",
  });

  if (result.error) throw result.error;
  if (result.status === 1) return true;
  if (result.status !== 0) {
    throw new Error(`git diff --cached failed with status ${result.status}`);
  }
  return false;
}

function assertCleanSubmodule(path) {
  const result = spawnSync(
    "git",
    ["status", "--porcelain", "--untracked-files=all"],
    { cwd: path, encoding: "utf8" },
  );

  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`Unable to inspect submodule at ${path}`);
  }
  if (result.stdout.trim()) {
    throw new Error(`Refusing to overwrite uncommitted changes in ${path}`);
  }
}

const backendDir = join(root, "backend");
const frontendDir = join(root, "frontend");
const cliDir = join(root, "cli");
const bundleDir = join(root, "bundle");
const frontendBuildDir = join(
  frontendDir,
  "dist",
  "snip-frontend",
  "browser",
);
const indexFile = join(frontendBuildDir, "index.html");

for (const path of [backendDir, frontendDir, cliDir, bundleDir]) {
  if (!existsSync(join(path, ".git")) && !existsSync(join(path, "server.js"))) {
    throw new Error(`Expected initialized submodule at ${path}`);
  }
  assertCleanSubmodule(path);
}

run("git", [
  "submodule",
  "update",
  "--init",
  "--remote",
  "backend",
  "frontend",
  "cli",
]);
runNpm("npm", ["install"], frontendDir);
runNpm("npx", ["ng", "build"], frontendDir);

if (!existsSync(indexFile)) {
  throw new Error(`Frontend build output is missing: ${indexFile}`);
}

copyFileSync(join(backendDir, "server.js"), join(bundleDir, "server.js"));
copyFileSync(join(cliDir, "cli.js"), join(bundleDir, "cli.js"));

const publicDir = join(bundleDir, "public");
rmSync(publicDir, { recursive: true, force: true });
mkdirSync(publicDir, { recursive: true });
cpSync(frontendBuildDir, publicDir, { recursive: true });

writeFileSync(join(bundleDir, ".env"), "PUBLIC_DIR=./public\n");
writeFileSync(
  join(bundleDir, "README.md"),
  [
    "# Generated Snip bundle",
    "",
    "This release is generated by `scripts/build-bundle.mjs` from the source",
    "submodules. Do not hand-edit these files.",
    "",
    "Start the API, redirects, and web UI with `bun start`. The CLI is",
    "available as `node cli.js`.",
    "",
  ].join("\n"),
);
writeFileSync(
  join(bundleDir, "package.json"),
  `${JSON.stringify({ name: "snip-bundle", private: true, scripts: { start: "bun server.js" } }, null, 2)}\n`,
);
writeFileSync(
  join(bundleDir, "Dockerfile"),
  [
    "FROM oven/bun:1-alpine",
    "WORKDIR /app",
    "COPY . .",
    "ENV PORT=3000",
    "EXPOSE 3000",
    'CMD ["bun", "server.js"]',
    "",
  ].join("\n"),
);
writeFileSync(
  join(bundleDir, ".dockerignore"),
  ["node_modules", ".git", ".gitmodules", "dist", ".angular", "*.log", ""].join("\n"),
);
writeFileSync(
  join(bundleDir, "railway.json"),
  `${JSON.stringify({ build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile" } }, null, 2)}\n`,
);

if (push.length === 1) {
  run("node", [join(root, "scripts", "smoke-test.mjs")]);
}

run("git", ["add", "--all"], bundleDir);
const bundleChanged = hasStagedChanges(bundleDir);
if (bundleChanged) {
  run(
    "git",
    [
      "commit",
      "-m",
      "Build generated Snip release bundle",
      "--trailer",
      "Co-authored-by=Copilot <223556219+Copilot@users.noreply.github.com>",
      "--trailer",
      "Co-authored-by=OpenBot <335604065+openbotgit[bot]@users.noreply.github.com>",
    ],
    bundleDir,
  );
} else {
  console.log("bundle unchanged");
}

run("git", ["add", "--", "backend", "frontend", "cli", "bundle"]);
const mainChanged = hasStagedChanges(root);
if (mainChanged) {
  run("git", [
    "commit",
    "-m",
    "Update generated bundle and source pointers",
    "--trailer",
    "Co-authored-by=Copilot <223556219+Copilot@users.noreply.github.com>",
    "--trailer",
    "Co-authored-by=OpenBot <335604065+openbotgit[bot]@users.noreply.github.com>",
  ]);
} else {
  console.log("main unchanged");
}

if (push.length === 1) {
  run("git", ["push", "origin", "HEAD:bundle"], bundleDir);
  run("git", ["push", "origin", "HEAD:main"]);
}

if (!bundleChanged && !mainChanged) console.log("unchanged");
